package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.scheduling.rules.*;import com.rpb.reservation.workforce.attendance.*;import com.rpb.reservation.workforce.scheduling.SchedulingDtos.*;import static com.rpb.reservation.workforce.scheduling.rules.AttendanceRules.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class BreakRulesCalculatorTest {
 Instant start=Instant.parse("2026-11-01T03:00:00Z");
 AttendanceRules rules(List<BreakRule> periods){return new AttendanceRules(1,periods,5,5,0,"excess",List.of(new AnomalyRule("LATE","迟到",true,true)),null,null);}
 Shift shift(AttendanceRules rules){return new Shift(UUID.randomUUID(),"11-23","11:00","23:00",false,"none",0,0,0,0,false,true,1,rules);}
 @Test void threeSeparateWindowsDeductFourHoursAndKeepLegacyJsonShape(){var rules=rules(List.of(new BreakRule("meal1","午餐","window",120,180,null,"none",false),new BreakRule("rest","中场","window",240,360,null,"none",false),new BreakRule("meal2","晚餐","window",540,600,null,"none",false)));AttendanceRules.validate(rules,720);var result=new AttendanceCalculator().calculate(shift(rules),start,start,start.plusSeconds(43200),List.of(),false);assertThat(result.breakSeconds()).isEqualTo(14400);assertThat(result.workSeconds()).isEqualTo(28800);var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();var legacy=new Shift(UUID.randomUUID(),"old","09:00","18:00",false,"none",0,0,0,0,false,true,1);assertThat(mapper.valueToTree(legacy).has("rules")).isFalse();}
 @Test void quotaUsesActualTimeAndReportsOverAndShortWithoutInventingBreaks(){var rule=rules(List.of(new BreakRule("rest","中场","quota",null,null,120,"required",false)));var calc=new BreakCalculator();var shortBreak=List.of(new AttendanceDtos.Interval(start.plusSeconds(3600),start.plusSeconds(9600),"rest"));var a=calc.calculate(rule,start,start,start.plusSeconds(43200),shortBreak);assertThat(a.workSeconds()).isEqualTo(37200);assertThat(a.summary().getFirst().shortSeconds()).isEqualTo(1200);var longBreak=List.of(new AttendanceDtos.Interval(start.plusSeconds(3600),start.plusSeconds(12600),"rest"));var b=calc.calculate(rule,start,start,start.plusSeconds(43200),longBreak);assertThat(b.summary().getFirst().overSeconds()).isEqualTo(1800);assertThat(b.workSeconds()).isEqualTo(34200);assertThat(calc.calculate(rule,start,start,start.plusSeconds(43200),List.of()).issues()).contains("BREAK_RECORD_MISSING");}
 @Test void invalidOverlappingPlannedPeriodsAndUnattributedActualBreaksAreRejected(){var r=rules(List.of(new BreakRule("a","a","window",60,180,null,"none",false),new BreakRule("b","b","window",120,240,null,"none",false)));assertThatThrownBy(()->AttendanceRules.validate(r,720)).isInstanceOf(RuntimeException.class);var two=rules(List.of(new BreakRule("a","a","actual",null,null,null,"optional",false),new BreakRule("b","b","actual",null,null,null,"optional",true)));assertThatThrownBy(()->new BreakCalculator().calculate(two,start,start,start.plusSeconds(43200),List.of(new AttendanceDtos.Interval(start.plusSeconds(60),start.plusSeconds(120))))).isInstanceOf(RuntimeException.class);}
 @Test void untrackedFixedWindowDoesNotClaimShortBreakAndActualWindowIsNotAQuota(){var fixed=rules(List.of(new BreakRule("meal","午餐","window",60,120,null,"none",false)));var a=new BreakCalculator().calculate(fixed,start,start,start.plusSeconds(43200),List.of()).summary().getFirst();assertThat(a.actualSeconds()).isNull();assertThat(a.shortSeconds()).isZero();assertThat(a.remainingSeconds()).isZero();var actual=rules(List.of(new BreakRule("rest","实际","actual",60,300,null,"optional",false)));var b=new BreakCalculator().calculate(actual,start,start,start.plusSeconds(43200),List.of(new AttendanceDtos.Interval(start.plusSeconds(3600),start.plusSeconds(7200),"rest"))).summary().getFirst();assertThat(b.plannedSeconds()).isZero();assertThat(b.shortSeconds()).isZero();assertThat(b.actualSeconds()).isEqualTo(3600);}
 @Test void paidBreaksDoNotReduceWorkAndOffsetsWorkAcrossMidnight(){Instant night=Instant.parse("2026-11-01T14:00:00Z");var r=rules(List.of(new BreakRule("paid","计薪休息","window",90,150,null,"none",true),new BreakRule("unpaid","不计薪休息","window",240,300,null,"none",false)));var result=new BreakCalculator().calculate(r,night,night,night.plusSeconds(43200),List.of());assertThat(result.breakSeconds()).isEqualTo(7200);assertThat(result.workSeconds()).isEqualTo(39600);}
}
